            "champ": "Nombre de factures"
          }
        }
      ],
      "passages_de_la_source": [
        "phrase : Le « CA du mois » du [[tableau-de-bord]] est égal au total de la [[liste-des-factures]].",
        "phrase : Le nombre de « Factures du mois » du [[tableau-de-bord]] est égal au nombre de factures de la [[liste-des-factures]]."
      ],
      "questions": []
    },
    {
      "id": "total-ttc-detail-egalite",
      "titre": "Détail facture : Total TTC égal au montant de la même facture dans la liste",
      "setup": "Connecté avec le compte de démo, sur le détail d’une facture, sans filtre.",
      "etapes": [
        "Cliquer sur le lien « Retour aux factures »."
      ],
      "resultat_attendu": "Le total TTC affiché correspond au montant TTC de la facture F-119 dans la liste.",
      "verifications": [
        "FAIL if le champ « Total TTC » du détail de la facture est différent du champ « Montant TTC de F-119 » de la liste des factures."
      ],
      "releves": [
        {
          "ecran": "detail-facture",
          "vue": "defaut"
        },
        {
          "ecran": "liste-des-factures",
          "vue": "defaut"
        }
      ],
      "regles_calculables": [
        {
          "type": "egalite",
          "a": {
            "ecran": "detail-facture",
            "champ": "Total TTC"
          },
          "b": {
            "ecran": "liste-des-factures",
            "champ": "Montant TTC de F-119"
          }
        }
      ],
      "passages_de_la_source": [
        "phrase : Le « Total TTC » du [[detail-facture]] est égal au montant de la même facture dans la [[liste-des-factures]]. Facture témoin : F-119."
      ],
      "questions": []
    }
  ]
}

